(() => {
 const form=document.querySelector('.ticket-focused #demo-login');if(!form)return;
 const phone=document.querySelector('#demo-phone'),error=document.querySelector('#ticket-phone-error'),stage=document.querySelector('#demo-login-step'),title=document.querySelector('#ticket-title'),description=document.querySelector('.ticket-description'),verification=document.querySelector('#ticket-verify'),send=document.querySelector('#ticket-send-code');
 if(!phone||!verification||!send||!error||!stage)return;
 function digits(){let value=phone.value.replace(/\D/g,'');return value.length===12&&value.startsWith('91')?value.slice(2):value;}
 function ready(){send.disabled=!/^[6-9]\d{9}$/.test(digits())||!verification.checked;}
 phone.addEventListener('input',()=>{error.textContent='';phone.removeAttribute('aria-invalid');phone.closest('.ticket-number').classList.remove('invalid');ready();});verification.addEventListener('change',ready);phone.addEventListener('blur',()=>{if(phone.value&&!/^[6-9]\d{9}$/.test(digits())){error.textContent='Enter a valid 10-digit Indian mobile number.';phone.setAttribute('aria-invalid','true');}});ready();
 form.addEventListener('submit',event=>{event.preventDefault();let number=digits();if(!/^[6-9]\d{9}$/.test(number)){error.textContent='Enter a valid 10-digit Indian mobile number.';phone.setAttribute('aria-invalid','true');phone.closest('.ticket-number').classList.add('invalid');phone.focus();return;}if(!verification.checked){error.textContent='Complete the preview verification.';verification.focus();return;}
  form.hidden=true;stage.hidden=false;title.textContent='Verify number.';description.textContent='Demo sign-in for +91 '+number.slice(0,5)+' '+number.slice(5)+'.';
  stage.innerHTML='<form id="ticket-code-form" novalidate><label for="ticket-code" class="ticket-label">Verification code</label><input class="ticket-code" id="ticket-code" name="code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="000000" aria-describedby="ticket-code-error ticket-code-hint"><p class="ticket-error" id="ticket-code-error" role="status"></p><button type="submit" class="ticket-continue">View demo tickets <span aria-hidden="true">↗</span></button><p class="ticket-preview-note" id="ticket-code-hint">Use 123456 for this local preview. No SMS was sent.</p><button type="button" class="ticket-change-number" id="ticket-back">Change mobile number</button></form>';
  const code=document.querySelector('#ticket-code');code.focus();code.addEventListener('input',()=>{document.querySelector('#ticket-code-error').textContent='';code.removeAttribute('aria-invalid');});
  document.querySelector('#ticket-back').addEventListener('click',()=>{stage.hidden=true;stage.innerHTML='';form.hidden=false;title.textContent='Your tickets';description.textContent='Sign in with the phone number you used at checkout to see every pass you’ve bought.';phone.focus();});
  document.querySelector('#ticket-code-form').addEventListener('submit',e=>{e.preventDefault();if(code.value!=='123456'){document.querySelector('#ticket-code-error').textContent='Use the demo code 123456.';code.setAttribute('aria-invalid','true');code.focus();return;}title.textContent='Your tickets.';description.textContent='A sample pass to try the EN3 experience.';stage.innerHTML='<div class="demo-ticket"><p class="ticket-success-heading">DEMO PASS · NOT VALID FOR ENTRY</p><h2>Jungle Safari</h2><p>Bandipur Tiger Reserve<br>Morning drive · 2 visitors</p><strong>DEMO-EN3</strong><p>No reservation or purchase was made.</p><a class="champ-link" href="/bandipur/book/jungle-safari">Explore booking ↗</a></div><button class="ticket-continue" id="ticket-signout">Sign out <span aria-hidden="true">↗</span></button>';document.querySelector('#ticket-signout').addEventListener('click',()=>location.reload());});
 });
})();
